`timescale 1ns / 1ps

// dralm_t6e: signed 8 x 8 dynamic-range approximate logarithmic multiplier DR-ALM-6
// of Yin et al. (IEEE TSUSC 6(4) 2021, Algorithm 1, eq. 7, Fig. 2-3): operands
// truncated to 6 bits from the leading one with the last bit forced to 1, +1
// compensation after the log adder, exact two's-complement sign units (not in the paper).
// A zero operand gives 0. Reference model: approx/dralm.py.
// a = weight, b = activation, p = a * b (signed, 16 bit).
// Generated by python3 -m src_gan_tsmc65.approx.gen (do not edit).

// logarithmic converter: x (> 0) -> {k, x_t}, k = leading-one position, x_t = the
// 4 bits after the leading one and a forced 1 (dynamic truncation, t = 6)
module dralm_t6e_log (
    input  wire [7:0] x,
    output wire [7:0] l
);
    reg [2:0] k;
    integer i;
    always @* begin
        k = 0;
        for (i = 1; i < 8; i = i + 1)
            if (x[i]) k = i;
    end
    wire [7:0] xs = x << (7 - k);       // leading one to bit 7
    assign l = {k, xs[6:3], 1'b1};
endmodule

// antilogarithmic converter + shifter: P = {1, L[t-2:0]} * 2^(L[top:t-1] - (t-1)),
// bits below the binary point dropped
module dralm_t6e_antilog (
    input  wire [8:0] l,
    output wire [15:0] p
);
    wire [5:0] mant = {1'b1, l[4:0]};
    wire [3:0] e = l[8:5];
    wire [20:0] s = {{(15){1'b0}}, mant} << e;
    assign p = s[20:5];
endmodule

module gan_mul8 (
    input  wire signed [7:0]  a,
    input  wire signed [7:0]  b,
    output wire signed [15:0] p
);
    // sign detector: exact two's-complement magnitude (|-128| = 128 fits 8 bits)
    wire [7:0] ma = a[7] ? -a : a;
    wire [7:0] mb = b[7] ? -b : b;
    wire [7:0] la, lb;
    dralm_t6e_log u_la (.x(ma), .l(la));
    dralm_t6e_log u_lb (.x(mb), .l(lb));
    // adder + compensation: both x_t LSBs are 1 and +2^-(t-1) is added, so the sum LSB
    // is 1 and the upper bits get a carry-in of 1
    wire [7:0] hi = la[7:1] + lb[7:1] + 1'b1;
    wire [8:0] l = {hi, 1'b1};
    wire [15:0] m;
    dralm_t6e_antilog u_al (.l(l), .p(m));
    wire zero = ~|a | ~|b;
    wire neg = a[7] ^ b[7];
    // sign set: exact negation
    assign p = zero ? 16'sd0 : (neg ? -$signed(m) : $signed(m));
endmodule
